function seedProducts(){
  return RAW.map(r=>{
    const R=rngOf(hashStr(r.id));const stock={};
    r.colors.forEach(c=>{stock[c]={};r.sizes.forEach(s=>{const v=R();stock[c][s]=v<.1?0:v<.26?Math.floor(R()*3)+1:Math.floor(R()*18)+4})});
    if(r.id==='k08'){stock.sky.XL=0;stock.sky.L=0}
    if(r.id==='k06')stock.black.S=0;
    if(r.id==='k16')stock.white['40']=0;
    if(r.id==='k01'){stock.lav.M=6;stock.lav.L=2}
    const d=DESC[r.tpl];
    return {...r,status:'active',desc:d[0],material:d[1],care:d[2],base:r.id,baseColors:r.colors.slice(),stock};
  });
}
function seedReviews(ps){
  const out=[];let n=1;
  ps.forEach(p=>{
    const R=rngOf(hashStr(p.id+'rv'));const k=3+Math.floor(R()*3);const pool=RV_TEXT[p.cat];const st=Math.floor(R()*5);
    for(let i=0;i<k;i++){
      const nm=NAMES[Math.floor(R()*NAMES.length)];const h=Math.round(152+R()*30),w=Math.round((h-108)*(.82+R()*.34));
      const si=p.sizes.length>1?Math.max(0,Math.min(p.sizes.length-1,Math.round((h-152)/30*(p.sizes.length-1)+(R()-.5)))):0;
      out.push({id:'r'+(n++),pid:p.id,name:nm,rating:R()<.66?5:R()<.84?4:3,text:pool[(st+i)%pool.length],daysAgo:Math.floor(R()*90)+2,verified:R()<.85,size:p.sizes[si],h,w,fitFeel:R()<.76?'true':R()<.5?'small':'large',color:p.colors[Math.floor(R()*p.colors.length)],status:'visible',img:null});
    }
  });
  return out;
}
