function seedOrders(ps,cs,now){
  const R=rngOf(20261118);const out=[];const avail=ps.slice();let seq=1040;
  const make=(cid,daysAgo,status,lines)=>{
    const c=cs.find(x=>x.id===cid);
    const items=lines.map(([pid,color,size,qty])=>{const p=ps.find(x=>x.id===pid);return{pid,name:p.name,color,size,qty,price:p.sale||p.price}});
    const sub=items.reduce((a,i)=>a+i.price*i.qty,0);const shipFee=sub>=1500000?0:30000;
    const o={id:'TT'+(seq++),cid,name:c.name,phone:c.phone,address:c.address,note:'',ship:'std',pay:R()<.7?'cod':'online',items,sub,discount:0,coupon:'',shipFee,total:sub+shipFee,status,at:now-daysAgo*DAY-Math.floor(R()*8)*36e5};
    out.push(o);return o;
  };
  for(let d=55;d>=4;d-=1.35+R()*.9){
    const cid='c'+(2+Math.floor(R()*12));const n=R()<.55?1:R()<.8?2:3;const lines=[];
    for(let k=0;k<n;k++){const p=avail[Math.floor(R()*avail.length)];const col=p.colors[Math.floor(R()*p.colors.length)];const sz=p.sizes.find(s=>p.stock[col][s]>0)||p.sizes[0];if(!lines.find(l=>l[0]===p.id))lines.push([p.id,col,sz,1]);}
    const st=d>10?(R()<.1?'cancelled':'delivered'):d>7?'shipping':d>5?'processing':'confirmed';
    make(cid,d,st,lines);
  }
  make('c3',1.4,'pending',[['k11','ltdenim','M',1],['k06','white','M',1]]);
  make('c6',.6,'pending',[['k16','white','42',1]]);
  make('c1',42,'delivered',[['k05','sky','M',1],['k15','black','M',1]]);
  make('c1',16,'delivered',[['k06','white','M',2],['k20','lav','One size',1]]);
  make('c1',3.5,'shipping',[['k07','navy','M',1]]);
  make('c1',1.1,'processing',[['k02','mint','M',1],['k22','lav','One size',1]]);
  return out.sort((a,b)=>b.at-a.at);
}
